namespace Footprint.Renderer;

internal static class FootprintChatPage
{
    public const string Html = """
<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Footprint Chat</title>
<style>
:root{--bg:#0f1117;--panel:#171a23;--panel2:#1e2330;--line:#2a3040;--text:#f4f6fb;--muted:#8f98ab;--accent:#7dd3fc;--bubble:#242a38;--mine:#1f4b59}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","PingFang SC",sans-serif}.app{display:grid;grid-template-columns:320px 1fr;height:100vh}.side{background:#141720;border-right:1px solid var(--line);padding:18px 14px;overflow:auto}.brand{font-size:17px;font-weight:700;margin:2px 8px 14px}.brand i{display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--accent);box-shadow:0 0 18px var(--accent);margin-right:8px}.nav{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:0 0 12px}.tab{height:34px;border:1px solid var(--line);border-radius:9px;background:#10131b;color:var(--muted);cursor:pointer}.tab.active{background:#263044;color:var(--text);border-color:#3b4860}.search{width:100%;height:38px;border:1px solid var(--line);border-radius:10px;background:#0f1219;color:var(--text);padding:0 12px;outline:0}.label{font-size:11px;letter-spacing:.14em;color:var(--muted);margin:20px 8px 8px}.thread,.contact,.favorite{display:flex;gap:10px;padding:11px 10px;border-radius:12px;margin:3px 0;cursor:pointer}.thread.active,.contact:hover,.favorite:hover{background:#222938}.avatar{width:38px;height:38px;border-radius:12px;background:#334155;display:grid;place-items:center;font-weight:700;flex:0 0 auto}.copy{min-width:0;flex:1}.top{display:flex;justify-content:space-between;gap:8px}.title{font-weight:650;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.time{font-size:11px;color:var(--muted)}.preview{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:4px}.main{display:flex;flex-direction:column;background:#11151e}.head{padding:17px 22px;border-bottom:1px solid var(--line)}.head h1{font-size:16px;margin:0}.head p{color:var(--muted);font-size:12px;margin:5px 0 0}.messages{padding:22px 28px;display:flex;flex-direction:column;gap:14px;overflow:auto;flex:1}.profile{margin:auto;width:min(460px,90%);padding:32px;border:1px solid var(--line);border-radius:20px;background:var(--panel);text-align:center}.profile .avatar{width:72px;height:72px;margin:0 auto 15px;border-radius:22px;font-size:26px}.profile h2{margin:0 0 7px}.profile p{margin:6px 0;color:var(--muted);font-size:12px;word-break:break-all}.profile button,.profile a{display:inline-block;margin-top:18px;padding:9px 16px;border:0;border-radius:9px;background:var(--accent);color:#08202b;font-weight:700;cursor:pointer;text-decoration:none}.msg{display:flex;gap:10px;max-width:78%}.bubble{background:var(--bubble);border:1px solid #303748;padding:11px 13px;border-radius:14px 14px 14px 5px;line-height:1.55;font-size:13px;word-break:break-word}.content{white-space:pre-wrap}.meta{font-size:10px;color:var(--muted);margin-top:6px}.kind{display:block;font-size:10px;color:var(--accent);margin-bottom:5px}.media-card{display:flex;align-items:center;gap:11px;min-width:240px;padding:10px;border:1px solid #3a4356;border-radius:11px;background:#1b202c}.media-icon{width:38px;height:38px;border-radius:10px;background:#303a4d;display:grid;place-items:center;font-size:19px}.media-title{font-weight:650}.media-desc{font-size:11px;color:var(--muted);margin-top:2px;max-width:360px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.raw{margin-top:8px;border-top:1px solid #353d50;padding-top:7px}.raw summary{cursor:pointer;color:var(--muted);font-size:11px;user-select:none}.raw pre{max-width:620px;max-height:220px;overflow:auto;white-space:pre-wrap;font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;color:#b7c0d2;background:#11151e;border-radius:8px;padding:9px}.empty{margin:auto;color:var(--muted)}@media(max-width:800px){.app{grid-template-columns:240px 1fr}.messages{padding:18px}.msg{max-width:90%}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><i></i>Footprint Chat</div><div class="nav"><button id="chat-tab" class="tab active">聊天</button><button id="contact-tab" class="tab">通讯录</button><button id="favorite-tab" class="tab">收藏</button></div><input id="search" class="search" placeholder="搜索会话"><div id="list-label" class="label">最近会话</div><div id="threads"></div></aside><main class="main"><header class="head"><h1 id="chat-title">选择一个会话</h1><p id="chat-sub">只读归档 · 消息内容来自解压后的 Footprint 数据</p></header><section id="messages" class="messages"><div class="empty">正在加载会话…</div></section></main></div>
<script>
const viewerToken=new URL(location.href).searchParams.get('token')||'';const threads=document.getElementById('threads');const messages=document.getElementById('messages');const search=document.getElementById('search');let sessions=[],contacts=[],favorites=[],mode='chats';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function get(path){const url=new URL(path,location.origin);url.searchParams.set('token',viewerToken);const r=await fetch(url);if(!r.ok)throw new Error(await r.text());return r.json()}
function splitMessageBody(value){const text=String(value??'');const marks=[text.indexOf('<?xml'),text.indexOf('<msg'),text.indexOf('<sysmsg')].filter(x=>x>=0);if(!marks.length)return{sender:'',content:text,xml:false};const start=Math.min(...marks);return{sender:start>0?text.slice(0,start).trim().replace(/:$/,''):'',content:text.slice(start),xml:true}}
function nodeText(doc,selector){return(doc.querySelector(selector)?.textContent||'').trim()}
function renderXml(xml,declaredKind){const doc=new DOMParser().parseFromString(xml,'application/xml');const broken=!!doc.querySelector('parsererror');let icon='◫',title='结构化消息',desc='点击查看原始 XML';if(!broken){if(doc.querySelector('img')){icon='🖼️';title='图片消息';desc='图片内容已采集为消息记录'}else if(doc.querySelector('emoji')){icon='🙂';title='表情消息';desc='微信表情'}else if(doc.querySelector('voicemsg,voice')){icon='🎙️';title='语音消息';desc='语音内容'}else if(doc.querySelector('videomsg,video')){icon='🎬';title='视频消息';desc='视频内容'}else if(doc.querySelector('appmsg')){icon='🔗';title=nodeText(doc,'appmsg > title')||'链接或文件消息';desc=nodeText(doc,'appmsg > des')||nodeText(doc,'appmsg > url')||'应用消息'}else if(doc.querySelector('sysmsg')){icon='ℹ️';title='系统消息';desc=nodeText(doc,'sysmsg')||'微信系统通知'}else{const plain=(doc.documentElement?.textContent||'').trim();if(plain){title=declaredKind==='text'?'消息内容':'结构化消息';desc=plain.slice(0,160)}}}return`<div class="media-card"><div class="media-icon">${esc(icon)}</div><div><div class="media-title">${esc(title)}</div><div class="media-desc">${esc(desc)}</div></div></div><details class="raw"><summary>查看原始 XML</summary><pre>${esc(xml)}</pre></details>`}
function renderMessage(m){const part=splitMessageBody(m.Body);return{sender:m.SenderName||part.sender||'未知发送者',html:part.xml?renderXml(part.content,m.Kind):`<div class="content">${esc(part.content)}</div>`}}
function formatMessageTime(value){if(!value||String(value).startsWith('1970-01-01'))return'时间未知';const date=new Date(value);return Number.isNaN(date.getTime())?'时间未知':date.toLocaleString('zh-CN',{hour12:false})}
function renderThreads(items){threads.innerHTML=items.map((s,i)=>`<div class="thread ${i===0?'active':''}" data-id="${esc(s.Id)}"><div class="avatar">${esc((s.Title||'?').slice(0,1))}</div><div class="copy"><div class="top"><div class="title">${esc(s.Title)}</div><div class="time">${esc((s.LastMessageUtc||'').slice(11,16))}</div></div><div class="preview">点击查看消息</div></div></div>`).join('');threads.querySelectorAll('.thread').forEach(el=>el.onclick=()=>{threads.querySelectorAll('.thread').forEach(x=>x.classList.remove('active'));el.classList.add('active');loadMessages(el.dataset.id,el.querySelector('.title').textContent)});if(items[0])loadMessages(items[0].Id,items[0].Title)}
function renderContacts(items){threads.innerHTML=items.map(c=>`<div class="contact" data-id="${esc(c.Id)}"><div class="avatar">${esc((c.DisplayName||'?').slice(0,1))}</div><div class="copy"><div class="title">${esc(c.DisplayName)}</div><div class="preview">${esc(c.Alias||c.SourceId)}</div></div></div>`).join('')||'<div class="empty">没有匹配的联系人</div>';threads.querySelectorAll('.contact').forEach(el=>el.onclick=()=>showContact(contacts.find(c=>c.Id===el.dataset.id)))}
function showContact(c){if(!c)return;document.getElementById('chat-title').textContent=c.DisplayName;document.getElementById('chat-sub').textContent='通讯录联系人';messages.innerHTML=`<div class="profile"><div class="avatar">${esc((c.DisplayName||'?').slice(0,1))}</div><h2>${esc(c.DisplayName)}</h2><p>微信标识：${esc(c.SourceId)}</p>${c.Alias?`<p>微信号：${esc(c.Alias)}</p>`:''}${c.SessionId?`<button id="open-chat">查看聊天记录</button>`:'<p>暂无聊天记录</p>'}</div>`;const button=document.getElementById('open-chat');if(button)button.onclick=()=>loadMessages(c.SessionId,c.DisplayName)}
function favoriteIcon(kind){return({link:'🔗',note:'📝',file:'📎',image:'🖼️',video:'🎬',voice:'🎙️'})[String(kind||'').toLowerCase()]||'⭐'}
function safeHttpUrl(value){try{const url=new URL(value);return url.protocol==='http:'||url.protocol==='https:'?url.href:''}catch{return''}}
function renderFavorites(items){threads.innerHTML=items.map(f=>`<div class="favorite" data-id="${esc(f.Id)}"><div class="avatar">${esc(favoriteIcon(f.Kind))}</div><div class="copy"><div class="title">${esc(f.Title||'未命名收藏')}</div><div class="preview">${esc(f.Kind)} · ${esc(formatMessageTime(f.CreatedAtUtc))}</div></div></div>`).join('')||'<div class="empty">本次归档未采集到收藏</div>';threads.querySelectorAll('.favorite').forEach(el=>el.onclick=()=>showFavorite(favorites.find(f=>f.Id===el.dataset.id)))}
function showFavorite(f){if(!f)return;const href=safeHttpUrl(f.Url);document.getElementById('chat-title').textContent=f.Title||'未命名收藏';document.getElementById('chat-sub').textContent='收藏详情';messages.innerHTML=`<div class="profile"><div class="avatar">${esc(favoriteIcon(f.Kind))}</div><h2>${esc(f.Title||'未命名收藏')}</h2><p>类型：${esc(f.Kind)}</p><p>收藏时间：${esc(formatMessageTime(f.CreatedAtUtc))}</p>${f.Url?`<p>${esc(f.Url)}</p>`:''}${href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer">打开链接</a>`:''}</div>`}
async function loadMessages(id,title){document.getElementById('chat-title').textContent=title;document.getElementById('chat-sub').textContent='只读归档 · 消息内容来自解压后的 Footprint 数据';messages.innerHTML='<div class="empty">正在加载消息…</div>';try{const rows=await get('/sessions/'+encodeURIComponent(id)+'/messages?limit=200');messages.innerHTML=rows.length?rows.map(m=>{const shown=renderMessage(m);return`<div class="msg"><div class="avatar">${esc((shown.sender||'?').slice(0,1))}</div><div><div class="bubble"><div class="kind">${esc(shown.sender)} · ${esc(m.Kind)}</div>${shown.html}</div><div class="meta">${esc(formatMessageTime(m.SentAtUtc))}</div></div></div>`}).join(''):'<div class="empty">这个会话没有可显示的消息</div>'}catch(e){messages.innerHTML='<div class="empty">加载失败：'+esc(e.message)+'</div>'}}
function setMode(next){mode=next;document.getElementById('chat-tab').classList.toggle('active',mode==='chats');document.getElementById('contact-tab').classList.toggle('active',mode==='contacts');document.getElementById('favorite-tab').classList.toggle('active',mode==='favorites');document.getElementById('list-label').textContent=mode==='chats'?'最近会话':mode==='contacts'?`聊天联系人 · ${contacts.length}`:`收藏 · ${favorites.length}`;search.placeholder=mode==='chats'?'搜索会话':mode==='contacts'?'搜索昵称、备注或微信号':'搜索收藏标题、类型或链接';search.value='';if(mode==='chats')renderThreads(sessions);else if(mode==='contacts')renderContacts(contacts);else renderFavorites(favorites)}
search.oninput=e=>{const q=e.target.value.trim().toLowerCase();if(mode==='chats')renderThreads(sessions.filter(s=>(s.Title||'').toLowerCase().includes(q)));else if(mode==='contacts')renderContacts(contacts.filter(c=>[c.DisplayName,c.Alias,c.SourceId].some(v=>(v||'').toLowerCase().includes(q))));else renderFavorites(favorites.filter(f=>[f.Title,f.Kind,f.Url].some(v=>(v||'').toLowerCase().includes(q))))};
document.getElementById('chat-tab').onclick=()=>setMode('chats');document.getElementById('contact-tab').onclick=()=>setMode('contacts');document.getElementById('favorite-tab').onclick=()=>setMode('favorites');
Promise.all([get('/api/sessions'),get('/api/contacts'),get('/api/favorites')]).then(([s,c,f])=>{sessions=s;contacts=c;favorites=f;renderThreads(s)}).catch(e=>messages.innerHTML='<div class="empty">加载失败：'+esc(e.message)+'</div>');
</script></body></html>
""";
}
